struct Frame{value:FieldValue,shape:Option<BorrowedShape>,record:Option<BorrowedRecordSpec>,remaining:usize,id:Option<u16>,last_id:Option<u16>,key:Option<String>,flags:u8,nodeflags:u8,field:u8,table:Option<Table>}
