fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,text)}
fn dynamic_scalar(value:&FieldValue)->bool{matches!(value,FieldValue::Bool(_)|FieldValue::Int(_)|FieldValue::UInt(_)|FieldValue::Float(_)|FieldValue::Text(_)|FieldValue::Bytes64(_)|FieldValue::Value(_))}
fn into_dynamic(value:FieldValue)->DslValue{match value{FieldValue::Bool(value)=>DslValue::Bool(value),FieldValue::Int(value)=>DslValue::Number(Number::Int(value)),FieldValue::UInt(value)=>DslValue::Number(Number::UInt(value)),FieldValue::Float(value)=>DslValue::Number(Number::Float(value)),FieldValue::Text(value)=>DslValue::String(value),FieldValue::Bytes64(value)=>DslValue::Bytes(value),FieldValue::Value(value)=>value,_=>unreachable!()}}
